mapper.select:
SELECT MAX(bid_price) as highestBid
FROM live_bid_history  WHERE live_auction_seq = #{seq} 
  AND status = 0

mapper.update:
UPDATE live_auction_schedule
SET broadcast_status = 2
WHERE seq = #{scheduleSeq} 
  AND live_auction_seq = #{auctionSeq}

UPDATE live_auction
SET winner_seq = #{winnerSeq}, 
    status = 2 WHERE seq = #{auctionSeq}
